-- Retire exact, backed-up PDA business procedures only. Default is a read-only preview.
-- Keep development TEST_RESET, POP authentication, MNT and all tables/data.
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET LOCK_TIMEOUT 10000;
DECLARE @Apply bit=0;
IF DB_NAME()<>N'AMES_DEV' THROW 52090, 'Select the intended AMES_DEV database explicitly.', 1;
DECLARE @Retired TABLE(Name sysname PRIMARY KEY, DefinitionHash varchar(64) NOT NULL);
INSERT @Retired(Name,DefinitionHash) VALUES
