IF EXISTS(SELECT 1 FROM @Retired WHERE Name LIKE '%TEST[_]RESET%' OR NOT (Name LIKE 'WH[_]PDA[_]%' OR Name LIKE 'FG[_]PDA[_]%' OR Name LIKE 'SP[_]PDA[_]%'))
    THROW 52090, 'Cleanup allowlist contains a non-business object.', 1;
IF @Apply=0
BEGIN
    SELECT R.Name,CASE WHEN P.object_id IS NULL THEN 'Already absent' ELSE 'Pending deletion' END AS State
    FROM @Retired R LEFT JOIN sys.procedures P ON P.schema_id=SCHEMA_ID('dbo') AND P.name=R.Name ORDER BY R.Name;
    RETURN;
END;
BEGIN TRY
    BEGIN TRANSACTION;
    IF EXISTS(
        SELECT 1 FROM @Retired R JOIN sys.procedures P ON P.schema_id=SCHEMA_ID('dbo') AND P.name=R.Name
        LEFT JOIN sys.sql_modules M ON M.object_id=P.object_id
        WHERE M.definition IS NULL OR CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),M.definition)),2)<>R.DefinitionHash)
        THROW 52090, 'A procedure changed since backup. Nothing removed; take a fresh backup first.', 1;
    IF EXISTS(
        SELECT 1 FROM sys.sql_expression_dependencies D
        JOIN sys.procedures P ON D.referenced_id=P.object_id
        JOIN @Retired R ON P.schema_id=SCHEMA_ID('dbo') AND P.name=R.Name
        WHERE NOT EXISTS(SELECT 1 FROM sys.procedures C JOIN @Retired X ON C.name=X.Name WHERE C.schema_id=SCHEMA_ID('dbo') AND C.object_id=D.referencing_id))
        THROW 52090, 'A retained database object references a retired procedure. Nothing removed.', 1;
    DECLARE @Command nvarchar(max)=N'';
    SELECT @Command=@Command+N'DROP PROCEDURE '+QUOTENAME('dbo')+N'.'+QUOTENAME(R.Name)+N';'+CHAR(10)
    FROM @Retired R JOIN sys.procedures P ON P.schema_id=SCHEMA_ID('dbo') AND P.name=R.Name;
    EXEC sys.sp_executesql @Command;
    IF EXISTS(SELECT 1 FROM @Retired R JOIN sys.procedures P ON P.schema_id=SCHEMA_ID('dbo') AND P.name=R.Name)
        THROW 52090, 'Cleanup verification failed.', 1;
    COMMIT TRANSACTION;
    SELECT COUNT(*) AS RetiredProcedureTargets FROM @Retired;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
